import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`demo-followup`,heroTitle:`Turn every demo into a closed deal`,heroSubtitle:`Perplexity Computer drafts personalized follow-up emails, schedules a multi-touch cadence, and references your exact discussion points — automatically.`,inputUrlCta:`Draft my follow-up`,inputUrlPlaceholder:`prospect-company.com`,inputUrlPrefill:`Go to {url} and gather context about this company — their industry, products, pain points, competitors, and recent news. Then ask me to describe the demo I just gave: who attended, what we discussed, key objections raised, features they were most interested in, agreed-upon next steps, and any relevant case studies. Using all of this, (1) Draft a personalized follow-up email to send within 24 hours that recaps specific discussion points, addresses objections, reinforces value props tied to their pain points, and includes a clear CTA for next steps. (2) Draft a 48-hour nudge email that shares a relevant case study or ROI data point tied to their industry. (3) Draft a 5-day follow-up that introduces additional resources — a product comparison, whitepaper, or testimonial — and re-engages on next steps. (4) Draft a 2-week breakup/re-engagement email with a compelling reason to reconnect. (5) For each email, include subject line variations, personalized opening lines, and specific CTAs. (6) Deliver a complete post-demo cadence summary with send dates, email previews, and a recommended outreach timeline I can execute immediately.`,heroOverlaySteps:[`Researching the prospect's company, industry, and recent news`,`Drafting personalized follow-up emails referencing your demo discussion points`,`Building a multi-touch cadence at 48 hours, 5 days, and 2 weeks`,`Complete post-demo email sequence with subject lines and send schedule — ready to send`],generatingSteps:[`Visiting {url} to research the prospect's company, products, and industry`,`Designing an agent to draft personalized follow-up emails tied to your demo talking points`,`Configuring multi-touch cadence with case studies, objection handling, and re-engagement triggers`,`Setting up complete email sequence with subject lines, send schedule, and CTA variations`],featureSectionTitle:`From demo notes to closing cadence`,featureCardTitles:[`Connects to your sales stack`,`Emails you can send today`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Gmail, Google Sheets, Pipedrive, Slack, Notion — Computer plugs into your tools so follow-ups, tracking, and team updates happen in one workflow.`,`Personalized openers. Case study references. Objection rebuttals. Subject line variations. Computer delivers a complete cadence ranked by deal-closing impact.`],capabilitySectionTitle:`Your sales follow-up team, on autopilot`,capabilitySectionSubtitle:`Describe your demo, step away, get a complete follow-up cadence.`,capabilityCards:[{title:`Prospect Research`,description:`Computer can research the prospect's company, industry, competitors, and recent news — so every follow-up email feels informed, not templated.`},{title:`Personalized Sequences`,description:`Computer can draft multi-touch email sequences that reference specific demo discussion points, objections, and agreed-upon next steps — with subject line variations for each.`},{title:`Case Study Matching`,description:`Computer can match relevant case studies, ROI data, and testimonials to the prospect's industry and pain points — and weave them into your follow-up cadence.`},{title:`Connect Your Tools`,description:`Computer can read from Gmail, Google Sheets, Pipedrive, Slack, and Notion — build workflows across your entire sales operation.`},{title:`Knows Your Deals`,description:`Computer can remember past demos, objection patterns, winning sequences, and deal outcomes — so every follow-up cadence gets sharper over time.`},{title:`Reply & Open Alerts`,description:`Computer can monitor your follow-up cadence for opens and replies — and alert you when a prospect engages or goes cold so you can act fast.`}]});export{t as default};
